<?php
namespace App\Controllers;
use App\Core\Controller;
use App\Models\Product;
use App\Models\Order;
use App\Models\Setting;
use App\Core\Database;
final class ShopController extends Controller {
 public function home():void{$p=new Product();$items=$p->publicList('',null,12);$cats=$p->categories();$this->view('shop/home',['items'=>$items,'categories'=>$cats,'settings'=>(new Setting())->allSettings(),'title'=>'KIN-MART Super Marché'],'shop');}
 public function catalog():void{$q=trim($_GET['q']??'');$cat=isset($_GET['category'])&&$_GET['category']!==''?(int)$_GET['category']:null;$p=new Product();$this->view('shop/catalog',['items'=>$p->publicList($q,$cat,100),'categories'=>$p->categories(),'q'=>$q,'category'=>$cat,'title'=>'Nos produits'],'shop');}
 public function product(string $id):void{$p=(new Product())->find((int)$id);if(!$p)redirect('catalog');$this->view('shop/product',['product'=>$p,'title'=>$p['name']],'shop');}
 public function cart():void{$cart=$this->cartItems();$this->view('shop/cart',$cart+['title'=>'Mon panier'],'shop');}
 public function addCart():void{$pid=(int)$_POST['product_id'];$qty=max(1,(int)($_POST['qty']??1));$p=(new Product())->find($pid);if(!$p){flash('error','Produit introuvable.');redirect('catalog');}$avail=(float)$p['quantity']-(float)$p['reserved_quantity'];$cur=(int)($_SESSION['shop_cart'][$pid]??0);if($cur+$qty>$avail){flash('error','Quantité indisponible.');redirect('cart');}$_SESSION['shop_cart'][$pid]=$cur+$qty;flash('success','Produit ajouté au panier.');redirect($_POST['return_to']??'cart');}
 public function updateCart():void{$pid=(int)$_POST['product_id'];$qty=(int)$_POST['qty'];if($qty<=0)unset($_SESSION['shop_cart'][$pid]);else $_SESSION['shop_cart'][$pid]=$qty;redirect('cart');}
 public function checkoutForm():void{if(($_SESSION['user']['role']??'')!=='CLIENT'){flash('error','Connectez-vous avec un compte client pour commander.');redirect('login');}$cart=$this->cartItems();if(!$cart['items'])redirect('cart');$zones=Database::connection()->query("SELECT * FROM delivery_zones WHERE status='ACTIVE' ORDER BY fee_usd,name")->fetchAll();$this->view('shop/checkout',$cart+['zones'=>$zones,'title'=>'Finaliser ma commande'],'shop');}
 public function checkout():void{if(($_SESSION['user']['role']??'')!=='CLIENT')redirect('login');$fulfillment=$_POST['fulfillment']??'RETRAIT';$zoneId=(int)($_POST['delivery_zone_id']??0);$fee=0.0;if($fulfillment==='LIVRAISON'){$z=Database::connection()->prepare("SELECT fee_usd FROM delivery_zones WHERE id=? AND status='ACTIVE'");$z->execute([$zoneId]);$fee=(float)($z->fetchColumn()?:0);if(!$zoneId)throw new \RuntimeException('Choisissez une zone de livraison.');}$d=['fulfillment'=>$fulfillment,'delivery_zone_id'=>$zoneId?:null,'delivery_fee'=>$fee,'commune'=>trim($_POST['commune']??''),'quartier'=>trim($_POST['quartier']??''),'avenue'=>trim($_POST['avenue']??''),'number'=>trim($_POST['number']??''),'reference_text'=>trim($_POST['reference_text']??''),'phone'=>trim($_POST['phone']??''),'instructions'=>trim($_POST['instructions']??''),'coupon_code'=>trim($_POST['coupon_code']??'')];try{$id=(new Order())->create((int)$_SESSION['user']['customer_id'],$_SESSION['shop_cart']??[],$d);unset($_SESSION['shop_cart']);flash('success','Commande enregistrée.');redirect('account/orders/'.$id);}catch(\Throwable $e){flash('error',$e->getMessage());redirect('checkout');}}
 public function account():void{if(($_SESSION['user']['role']??'')!=='CLIENT')redirect('login');$cid=(int)$_SESSION['user']['customer_id'];$c=(new \App\Models\Customer())->find($cid);$orders=(new Order())->list($cid);$recommendations=\App\Services\RecommendationService::forCustomer($cid);$this->view('shop/account',['customer'=>$c,'orders'=>$orders,'recommendations'=>$recommendations,'title'=>'Mon compte'],'shop');}
 public function accountOrder(string $id):void{if(($_SESSION['user']['role']??'')!=='CLIENT')redirect('login');$o=(new Order())->find((int)$id);if(!$o||(int)$o['customer_id']!==(int)$_SESSION['user']['customer_id']){http_response_code(403);exit('Accès refusé');}$this->view('shop/order',['order'=>$o,'title'=>'Commande '.$o['order_no']],'shop');}
 public function favorite():void{if(($_SESSION['user']['role']??'')!=='CLIENT')redirect('login');$pid=(int)$_POST['product_id'];$db=Database::connection();$db->prepare("INSERT IGNORE INTO favorite_products(customer_id,product_id) VALUES(?,?)")->execute([$_SESSION['user']['customer_id'],$pid]);flash('success','Ajouté aux favoris.');redirect('catalog');}
 private function cartItems():array{$cart=$_SESSION['shop_cart']??[];$p=new Product();$items=[];$total=0;foreach($cart as $id=>$qty){$x=$p->find((int)$id);if(!$x)continue;$x['cart_qty']=$qty;$x['line_total']=$qty*(float)($x['effective_price']??$x['sale_price']);$items[]=$x;$total+=$x['line_total'];}return compact('items','total');}
}
